# The first stem 0-10 isn't forming. The issue: pos 0-3 paired with 7-10 needs GC.
# But pos 0-3 and the last stem 297-307 must not be complementary.
# Solution: keep stem1 GC, but make the LAST stem (297-307) use AU so 0(G)-307(U) doesn't pair.
# Also pos 7-10 (C's) vs 297-300: if 297-300 is AU (A's), 7-10 C vs A = no pair. Good.
# Let me also check: the first attempt had 0-307 spurious because both were GC. Now stem1 GC, last stem AU.

t='((((...))))(((((((....))(((((..(((((((....))(((((((((...))))..((((...)))))))))((....)))))))..(((((((....))(((((((((...))))..((((...)))))))))((....)))))))..(((((((....))(((((((((...))))..((((...)))))))))((....)))))))..(((((((....))(((((((((...))))..((((...)))))))))((....)))))))..)))))((....)))))))((((...))))'
n=len(t)
stack=[]; pair=[-1]*n
for i,c in enumerate(t):
    if c=='(': stack.append(i)
    elif c==')': j=stack.pop(); pair[i]=j; pair[j]=i
seq=['A']*n
for i in range(n):
    if pair[i]!=-1 and i<pair[i]:
        seq[i]='G'; seq[pair[i]]='C'
# Make LAST stem (297-307) use AU: pairs (297,307)(298,306)(299,305)(300,304)
for (i,j) in [(297,307),(298,306),(299,305),(300,304)]:
    seq[i]='A'; seq[j]='U'
