for (a,b),m in caps.items():
    for k,c in enumerate(m): seq[a+k]=c
for i in range(n):
    if pair[i]==-1 and t[i]=='.':
        if not any(a<=i<b for (a,b) in caps):
            seq[i]='A'
s=''.join(seq)
print(s)
open('/tmp/seq3.txt','w').write(s)
